insert into public.tasks (id, class_id, section_id, title, description, difficulty, world) values
('course-1-1', null, null, 'Первая доставка', 'Доставь машину по прямой к флагу. Посчитай клетки и задай точное число шагов.', 'easy', '{"width":6,"height":3,"start":{"x":0,"y":1,"direction":"east"},"goal":{"x":3,"y":1},"obstacles":[]}'::jsonb),
('course-1-2', null, null, 'Команды по порядку', 'Доедь до флага за углом. Используй движение и поворот в правильном порядке, не задень препятствие.', 'easy', '{"width":5,"height":5,"start":{"x":1,"y":3,"direction":"east"},"goal":{"x":3,"y":1},"obstacles":[{"x":2,"y":2}]}'::jsonb),
('course-2-1', null, null, 'Два поворота', 'Собери маршрут вокруг преграды. Для зачёта машина должна выполнить не менее двух поворотов и дойти до флага.', 'easy', '{"width":6,"height":5,"start":{"x":1,"y":3,"direction":"east"},"goal":{"x":4,"y":1},"obstacles":[{"x":3,"y":3},{"x":3,"y":2}]}'::jsonb),
('course-2-2', null, null, 'Выезд с парковки', 'Впереди машины стена. Используй хотя бы один шаг назад, затем доберись до парковочного флага.', 'easy', '{"width":6,"height":4,"start":{"x":4,"y":2,"direction":"east"},"goal":{"x":1,"y":1},"obstacles":[{"x":5,"y":2},{"x":4,"y":3}]}'::jsonb),
('course-3-1', null, null, 'Шесть шагов циклом', 'Доедь до флага с помощью цикла. Цикл должен выполнить движение хотя бы в двух повторениях; простая запись шести шагов не засчитывается.', 'medium', '{"width":8,"height":3,"start":{"x":0,"y":1,"direction":"east"},"goal":{"x":6,"y":1},"obstacles":[]}'::jsonb),
('course-3-2', null, null, 'Лестница повторений', 'Пройди лестницу к флагу. В повторяющемся фрагменте должны выполняться и движение, и повороты.', 'medium', '{"width":6,"height":6,"start":{"x":0,"y":5,"direction":"east"},"goal":{"x":4,"y":1},"obstacles":[{"x":1,"y":2},{"x":2,"y":2},{"x":3,"y":1},{"x":2,"y":5},{"x":3,"y":4},{"x":4,"y":3}]}'::jsonb),
('course-4-1', null, null, 'Решение перед преградой', 'Машина смотрит на препятствие. Проверь его условием и выполни действие в ветке «если», затем доберись до флага.', 'medium', '{"width":4,"height":4,"start":{"x":1,"y":3,"direction":"north"},"goal":{"x":2,"y":2},"obstacles":[{"x":1,"y":2}]}'::jsonb),
('course-4-2', null, null, 'Одна программа — две карты', 'Одна программа должна дойти до флага на обеих картах. На первой путь впереди закрыт, на второй свободен. Используй действующие ветки if и else.', 'medium', '{"width":5,"height":5,"start":{"x":1,"y":3,"direction":"north"},"goal":{"x":3,"y":1},"obstacles":[{"x":1,"y":2}]}'::jsonb),
('course-6-1', null, null, 'Проект: патруль до станции', 'Доставь машину на станцию. Объедини цикл движения и условие: при преграде измени направление. Обе конструкции должны сработать.', 'hard', '{"width":7,"height":6,"start":{"x":1,"y":4,"direction":"east"},"goal":{"x":5,"y":1},"obstacles":[{"x":6,"y":4},{"x":2,"y":2},{"x":3,"y":2}]}'::jsonb),
('course-6-2', null, null, 'Отладка: неверный поворот', 'В стартовой программе неверный поворот. Исправь её, сохрани работающие цикл и условие и доберись до флага не более чем за 7 шагов движения.', 'hard', '{"width":8,"height":6,"start":{"x":1,"y":4,"direction":"east"},"goal":{"x":6,"y":2},"obstacles":[{"x":7,"y":4},{"x":2,"y":1},{"x":3,"y":1},{"x":4,"y":1}]}'::jsonb)
